# apply_gbm_and_run.py — installs LightGBM, drops 4 new files, and compares
# PL+qual baseline vs. GBM ranker on real backfilled data.
import base64, os, sys, pathlib, subprocess

FILES = {
    'src/features/rolling.py': '',
    'src/features/build_features.py': '',
    'src/models/gbm_ranker.py': '',
    'src/eval/backtest_gbm.py': '',
}


def main():
    # 0. ensure LightGBM is installed
    try:
        import lightgbm  # noqa: F401
    except ImportError:
        print("Installing lightgbm ...")
        subprocess.run([sys.executable, "-m", "pip", "install", "-q", "lightgbm"], check=True)

    # 1. write files
    for target, b64 in FILES.items():
        p = pathlib.Path(target)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(base64.b64decode(b64))
        print(f"wrote {target}")

    # 2. compare
    import pandas as pd
    from src.eval.backtest import backtest as pl_backtest, summarize as pl_summarize
    from src.eval.backtest_gbm import backtest_gbm, summarize_gbm

    races = pd.read_parquet("data/processed/races.parquet").sort_values("date").reset_index(drop=True)
    entries = pd.read_parquet("data/processed/entries.parquet")
    sessions = pd.read_parquet("data/processed/sessions.parquet")

    print("\n=== PL BASELINE + QUAL (walk-forward, burn-in 36) ===")
    _, per_race = pl_backtest(races, entries, burn_in_races=36, sessions=sessions, qual_weight=0.4)
    print(pl_summarize(per_race).round(4).to_string())

    print("\n=== GBM RANKER (train 2022+2023, test 2024+2025+2026) ===")
    model, df, feats = backtest_gbm(races, entries, sessions=sessions, split_date="2024-01-01", score_scale=0.5)
    print(f"train races: {(feats['date'] < pd.Timestamp('2024-01-01')).groupby(feats['race_id_short']).any().sum()}")
    print(f"test races:  {len(df)}")
    print(summarize_gbm(df).round(4).to_string())

    # 3. Feature-importance quick peek
    try:
        booster = model.booster
        imp = pd.DataFrame({
            "feature": booster.feature_name(),
            "gain": booster.feature_importance(importance_type="gain"),
        }).sort_values("gain", ascending=False).head(12)
        print("\nTop features by gain:")
        print(imp.to_string(index=False))
    except Exception as e:
        print(f"(couldn't extract feature importance: {e})")

if __name__ == "__main__":
    main()
